struct Node;

fn encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => out.push(b as char),
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Approved enrichment fetch. The result is deliberately ignored so the
        // output is unaffected; `fetch` returns transport failures as values.
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode(&info.date)
        );
        let _ = crate::aap::caps::http_client::fetch(&url);

        let raw = crate::aap::caps::state_read::get("urls").unwrap_or_default();
        let urls: Vec<String> = raw
            .lines()
            .map(|l| l.trim())
            .filter(|l| !l.is_empty())
            .map(|l| l.to_string())
            .collect();

        SubscriptionList { urls }
    }
}

export!(Node);
```

The `RunInfo` input has no text field, so I used its `date` as the `q` value, percent-encoded. I used `fetch` instead of `get` so a failed request returns an error value and doesn't trap. The result is discarded, so the output is unchanged.

I assumed the store key is `"urls"` with newline-separated values. The spec doesn't name the key, so change it if the store uses another.

